                                                                                                                                                                                                     
  CREATE TABLE "FND_AREAS"                                                                                                                                                                
   (	"AREA_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 3 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                 
	"REMARK" NVARCHAR2(512),                                                                                                                                                                            
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                               
	"IS_ENABLE" NUMBER NOT NULL ENABLE,                                                                                                                                                                 
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                 
	"TYPE" NUMBER NOT NULL ENABLE,                                                                                                                                                                      
	"FAB_ID" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                    
	"SYSTEM_CODE" NVARCHAR2(20),                                                                                                                                                                        
	"SORT_NUM" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	 PRIMARY KEY ("AREA_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

